from decimal import Decimal
from ledgerly.gateway import PaymentGateway
from ledgerly.models import Payment
from ledgerly.provider_refunds import refund_via_provider
from ledgerly.errors import BillingError

def mk(): return Payment("p","i",Decimal("100.00"),status="captured")

# lost then ok -> single refund, no double money
p=mk(); g=PaymentGateway(["lost","ok"]); refund_via_provider(p,Decimal("40.00"),g)
print("lost+ok:", p.refunded_amount, p.provider_refund_ids, g.money_moved, len(g.calls))

# all timeouts -> unchanged, error
p=mk(); g=PaymentGateway(["timeout","timeout","timeout"])
try: refund_via_provider(p,Decimal("40.00"),g)
except BillingError as e: print("timeout:", e.code, p.refunded_amount, p.status, len(g.calls))

# full refund
p=mk(); refund_via_provider(p,Decimal("100.00"),PaymentGateway()); print("full:", p.status, p.refunded_amount)

# over refund
p=mk()
try: refund_via_provider(p,Decimal("101.00"),PaymentGateway())
except BillingError as e: print("over:", e.code)

# not captured
p=Payment("p","i",Decimal("100.00"),status="authorized")
try: refund_via_provider(p,Decimal("10.00"),PaymentGateway())
except BillingError as e: print("state:", e.code)

# non-positive
p=mk()
try: refund_via_provider(p,Decimal("0"),PaymentGateway())
except BillingError as e: print("nonpos:", e.code)
EOF"}

